
.ls-ring {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
}

.ls-ring-dial {
  position: relative;
  width: 68px;
  height: 68px;
}

.ls-ring-svg {
  display: block;
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.ls-ring-track {
  fill: none;
  stroke: var(--ls-border);
  stroke-width: 5;
}

.ls-ring-fill {
  fill: none;
  stroke-width: 5;
  stroke-linecap: round;
  transition: stroke-dashoffset 0.55s var(--ls-ease-out), stroke 0.2s var(--ls-ease);
}

.ls-ring-value {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  font-weight: 600;
  color: var(--ls-text);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}

.ls-ring-label {
  font-size: 12.5px;
  color: var(--ls-text-muted);
}
