
.ls-opening {
  display: flex;
  flex-direction: column;
  background: var(--ls-surface);
  border: 1px solid var(--ls-border);
  border-radius: var(--ls-r-md);
  overflow: hidden;
  animation: ls-enter 0.5s var(--ls-ease-out) both;
}

.ls-opening-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 20px 18px 18px;
}

.ls-opening-title {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.015em;
  color: var(--ls-text);
}

.ls-opening-tabs {
  display: flex;
  gap: 2px;
  margin: 0 16px;
  padding: 3px;
  border-radius: var(--ls-r-sm);
  background: var(--ls-bg-alt);
}

.ls-opening-tab {
  flex: 1;
  padding: 6px 0;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--ls-text-muted);
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
}

.ls-opening-tab:hover {
  color: var(--ls-text);
}

.ls-opening-tab.ls-is-active {
  background: var(--ls-surface);
  color: var(--ls-text);
  box-shadow: var(--ls-shadow-hair);
}

.ls-opening-body {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 16px;
}

.ls-tpl {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 14px 15px;
  border: 1px solid var(--ls-border);
  border-radius: var(--ls-r-sm);
  background: var(--ls-surface);
  text-align: left;
  cursor: pointer;
  animation: ls-enter 0.42s var(--ls-ease-out) both;
}

.ls-tpl:nth-child(2) {
  animation-delay: 50ms;
}

.ls-tpl:nth-child(3) {
  animation-delay: 100ms;
}

.ls-tpl:hover {
  background: var(--ls-surface-sunken);
  border-color: var(--ls-border-strong);
}

.ls-tpl-index {
  font-size: 11px;
  color: var(--ls-accent);
  letter-spacing: 0.2em;
}

.ls-tpl-title {
  font-size: 14.5px;
  font-weight: 500;
  color: var(--ls-text);
}

.ls-tpl-meta {
  font-size: 12px;
  color: var(--ls-text-faint);
}

.ls-tpl-desc {
  margin-top: 3px;
  font-family: var(--ls-f-serif);
  font-size: 13.5px;
  line-height: 1.7;
  color: var(--ls-text-body);
}

.ls-tpl-cast {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 6px;
}

.ls-tpl-person {
  padding: 2px 9px;
  border-radius: 999px;
  background: var(--ls-bg-alt);
  font-size: 11px;
  color: var(--ls-text-muted);
}

.ls-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.ls-field-label {
  font-size: 12px;
  color: var(--ls-text-muted);
}

.ls-field-area,
.ls-field-input {
  width: 100%;
  padding: 9px 11px;
  border: 1px solid var(--ls-border-strong);
  border-radius: var(--ls-r-sm);
  background: var(--ls-surface);
  color: var(--ls-text);
  font-size: 13.5px;
  line-height: 1.6;
  outline: none;
  resize: vertical;
}

.ls-field-area::placeholder {
  color: var(--ls-text-faint);
}

.ls-field-area:focus,
.ls-field-input:focus {
  border-color: var(--ls-accent);
  box-shadow: 0 0 0 3px var(--ls-accent-soft);
}

.ls-field-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.ls-sex-row {
  display: flex;
  gap: 8px;
}

.ls-sex {
  flex: 1;
  padding: 8px 0;
  border: 1px solid var(--ls-border-strong);
  border-radius: var(--ls-r-sm);
  background: var(--ls-surface);
  color: var(--ls-text-body);
  font-size: 13.5px;
  cursor: pointer;
}

.ls-sex:hover {
  background: var(--ls-surface-sunken);
}

.ls-sex.ls-is-active {
  border-color: var(--ls-accent);
  background: var(--ls-accent-soft);
  color: var(--ls-accent-hover);
  font-weight: 500;
}

.ls-trait-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(158px, 1fr));
  gap: 8px 18px;
}

.ls-trait {
  display: flex;
  align-items: center;
  gap: 10px;
}

.ls-trait-name {
  flex: none;
  width: 32px;
  font-size: 12.5px;
  color: var(--ls-text-body);
}

.ls-trait-range {
  flex: 1;
  min-width: 0;
  height: 4px;
  appearance: none;
  border-radius: 999px;
  background: var(--ls-border-strong);
  outline: none;
  cursor: pointer;
}

.ls-trait-range::-webkit-slider-thumb {
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--ls-accent);
  border: 2px solid var(--ls-surface);
  box-shadow: var(--ls-shadow-hair);
}

.ls-trait-range::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--ls-accent);
  border: 2px solid var(--ls-surface);
}

.ls-trait-value {
  flex: none;
  min-width: 28px;
  text-align: right;
  font-size: 13px;
  font-weight: 500;
  color: var(--ls-text);
  font-variant-numeric: tabular-nums;
}

.ls-random {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 20px;
  border: 1px dashed var(--ls-border-strong);
  border-radius: var(--ls-r-sm);
  background: var(--ls-surface-sunken);
  color: var(--ls-text-body);
  font-size: 13.5px;
  cursor: pointer;
}

.ls-random:hover {
  border-color: var(--ls-accent);
  background: var(--ls-accent-soft);
  color: var(--ls-accent-hover);
}

.ls-opening-foot {
  display: flex;
  flex-direction: column;
  gap: 9px;
  padding: 0 16px 16px;
}

.ls-begin {
  padding: 11px 0;
  border: none;
  border-radius: var(--ls-r-sm);
  background: var(--ls-accent);
  color: #ffffff;
  font-size: 13.5px;
  font-weight: 500;
  cursor: pointer;
}

.ls-begin:not(:disabled):hover {
  background: var(--ls-accent-hover);
}

.ls-begin:disabled {
  background: var(--ls-border-strong);
  color: var(--ls-bg-alt);
  cursor: default;
}

.ls-opening-hint {
  min-height: 16px;
  text-align: center;
  font-size: 12px;
  color: var(--ls-accent-hover);
}
