
.ls-age {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.ls-age-dial {
  position: relative;
  width: 62px;
  height: 62px;
}

.ls-age-svg {
  display: block;
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.ls-age-track {
  fill: none;
  stroke: var(--ls-border);
  stroke-width: 4;
}

.ls-age-fill {
  fill: none;
  stroke: var(--ls-accent);
  stroke-width: 4;
  stroke-linecap: round;
  transition: stroke-dashoffset 0.55s var(--ls-ease-out);
}

.ls-age-center {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 500;
  color: var(--ls-accent-hover);
  letter-spacing: -0.01em;
}

.ls-age-range {
  font-size: 10.5px;
  color: var(--ls-text-faint);
  font-variant-numeric: tabular-nums;
}
