
.ls-focus {
  display: flex;
  align-items: center;
  gap: 18px;
}

.ls-focus-dial {
  position: relative;
  flex: none;
  width: 108px;
  height: 108px;
}

.ls-focus-svg {
  display: block;
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.ls-focus-track {
  fill: none;
  stroke: var(--ls-border);
  stroke-width: 10;
}

.ls-focus-arc {
  fill: none;
  stroke-width: 10;
  transition: stroke-dasharray 0.5s var(--ls-ease-out), stroke-dashoffset 0.5s var(--ls-ease-out);
}

.ls-focus-center {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 19px;
  font-weight: 600;
  color: var(--ls-text);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}

.ls-focus-center.ls-is-over {
  color: var(--ls-alarm);
}

.ls-focus-legend {
  display: flex;
  flex-direction: column;
  gap: 7px;
  min-width: 0;
}

.ls-focus-item {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12.5px;
  color: var(--ls-text-body);
}

.ls-focus-dot {
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.ls-focus-field {
  color: var(--ls-text);
}

.ls-focus-item b {
  margin-left: auto;
  font-weight: 600;
  color: var(--ls-text-muted);
  font-variant-numeric: tabular-nums;
}

.ls-empty {
  font-size: 12.5px;
  color: var(--ls-text-faint);
}
