
.ls-level {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.ls-level-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.ls-level-name {
  /* 名称过长时先让位，保证右侧的类标签与数值不被挤掉 */
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  font-size: 13px;
  color: var(--ls-text);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ls-level-category {
  flex: none;
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--ls-bg-alt);
  color: var(--ls-text-muted);
  font-size: 11px;
  line-height: 1.5;
}

.ls-level-meta {
  display: flex;
  align-items: baseline;
  gap: 7px;
  margin-left: auto;
  font-variant-numeric: tabular-nums;
}

.ls-level-meta b {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--ls-accent-hover);
}

.ls-level-pct {
  font-size: 11.5px;
  color: var(--ls-text-muted);
}

.ls-level-quality {
  font-size: 11px;
  color: var(--ls-text-faint);
}

.ls-level-cap {
  font-size: 11px;
  color: var(--ls-text-faint);
}

.ls-level-track {
  display: flex;
  gap: 3px;
  height: 6px;
}

.ls-level-cell {
  position: relative;
  flex: 1;
  border-radius: 2px;
  background: var(--ls-border);
  overflow: hidden;
}

.ls-level-cell.ls-is-done {
  background: var(--ls-accent);
}

.ls-level-cell.ls-is-capped {
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--ls-border);
}

.ls-level-fill {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  border-radius: 2px;
  background: var(--ls-accent);
  transition: width 0.45s var(--ls-ease-out);
}
