
.ls-archive {
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding: 16px;
}

.ls-vitals {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.ls-group {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.ls-group-label {
  font-size: 12px;
  color: var(--ls-text-faint);
}

.ls-rel-list {
  --ls-collapse-gap: 11px;
}

.ls-empty {
  font-size: 12.5px;
  color: var(--ls-text-faint);
}

.ls-asset-groups {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ls-asset-group {
  display: flex;
  flex-direction: column;
  padding: 6px 12px 8px;
  border: 1px solid var(--ls-border);
  border-radius: var(--ls-r-sm);
  background: var(--ls-surface-sunken);
}

.ls-asset-group-label {
  padding: 4px 0 6px;
  font-size: 11px;
  letter-spacing: 0.1em;
  color: var(--ls-text-faint);
}

.ls-asset-row {
  display: flex;
  align-items: baseline;
  gap: 12px;
  padding: 9px 0;
  border-top: 1px solid var(--ls-border);
}

.ls-asset-row:first-child {
  border-top: none;
}

.ls-asset-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.ls-asset-name {
  font-size: 13px;
  color: var(--ls-text);
}

.ls-asset-source {
  font-size: 11.5px;
  color: var(--ls-text-faint);
}

.ls-asset-amount {
  margin-left: auto;
  flex: none;
  font-size: 13px;
  font-weight: 600;
  color: var(--ls-accent-hover);
  font-variant-numeric: tabular-nums;
}
