
.ls-skills {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 16px;
}

.ls-group {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.ls-group-label {
  font-size: 12px;
  color: var(--ls-text-faint);
}

.ls-skill-list {
  --ls-collapse-gap: 11px;
}

.ls-ghost {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.ls-ghost-note {
  font-size: 12.5px;
  color: var(--ls-text-faint);
}

.ls-ghost-track {
  display: flex;
  gap: 3px;
  height: 6px;
}

.ls-ghost-cell {
  flex: 1;
  border-radius: 2px;
  box-shadow: inset 0 0 0 1px var(--ls-border);
}
