
.ls-radar {
  display: flex;
  justify-content: center;
  padding: 14px 16px 16px;
}

.ls-radar-svg {
  display: block;
  width: 100%;
  max-width: 300px;
  height: auto;
}

.ls-radar-grid {
  fill: none;
  stroke: var(--ls-border);
  stroke-width: 1;
}

.ls-radar-axis {
  stroke: var(--ls-border);
  stroke-width: 1;
}

.ls-radar-area {
  fill: var(--ls-accent-soft);
  stroke: var(--ls-accent);
  stroke-width: 1.5;
  stroke-linejoin: round;
}

.ls-radar-dot {
  fill: var(--ls-accent);
}

.ls-radar-label {
  font-size: 11.5px;
  fill: var(--ls-text-body);
}

.ls-radar-value {
  font-size: 11px;
  font-weight: 600;
  fill: var(--ls-accent-hover);
  font-variant-numeric: tabular-nums;
}
